    "description": "Компания Raven Microcyb только что выпустила на рынок эти шикарные устройства. Устройства для перевода в режиме реального времени. Когда вы видите или слышите слова, чип переводит их на выбранный вами язык и проецирует текст на ваш Хирон. Щепка. Требуется Хирон. Любые слова на языке, которые слышит или читает пользователь, переводятся на выбранный вами язык и отображаются на Хироне в виде субтитров в режиме реального времени. По усмотрению Рефери, редкие «мертвые» языки или языки и диалекты, на которых говорят небольшие и/или изолированные группы населения, чип не может перевести. Перевод сленговых терминов осуществляется с перебоями, поскольку язык развивается быстрее, чем Raven Microcybernetics успевает выпускать обновления. Чип-переводчик не позволяет пользователю говорить на каких-либо дополнительных языках."
