    "description": "Стандартная подкожная броня больше не подходит, а Тканекожа считай что мусор! Чтобы не отставать от огневой мощи, которой обладают люди в наши дни, тебе нужны крепкие бронепластины под кожей. Большие, тяжелые, останавливающие все пули.Является Боргированием. Внешний киберимплант. Подкожная броня. Для установки требуется ТЕЛО 10, если только на пользователе нет корпуса ПКТ. Дает 13 ОС для тела и головы. Пользователь получает штраф к броне -2 к РЕА, ЛВК и СКО, если он не имеет ТЕЛО 14 или выше или если пользователь не перешёл на ПКТ. Тяжелая Подкожная Броня содержит наноботов, которые восстанавливают ее на 1 очко потерянных ОС в конце каждого дня, если она не теряла ОС в этот день.Примечание: При установке на корпус ПКТ Тяжелая Подкожная Броня обычно не является подкожной, а действует как кожа пользователя, обладая осязанием."
