    "humanityCostFormula": "7 (2d6)",
    "costEb": 100,
    "description": "Замена руки. Не обязательно парная. Нео-Советская Киберрука имеет 3 слота опций Киберруки или Киберконечности и поставляется со Стандартной Кистью, которая не провоцирует Потерю Человечности и не занимает слот для опций Киберруки. Без ТЕЛ 8 или выше, вы получаете -1 ко всем броскам, которые требуют использования этой руки.Все опции, установленные в руке, всегда видны невооруженным глазом, когда она раскрыта, из-за ее неэффективной и выпуклой конструкции. Сюда входят и те варианты оружия, которые считались бы скрытыми в другой Киберруке.Нео-Советская Киберрука всегда распознается как Киберрука, даже с покрытием РеалскинTM."
