    "description": "Киберрука. Не обязательно парная. Имеет 0 слотов модулей Киберруки или Киберконечности. В руку не встроена кисть, поэтому ей нельзя ничего держать.Это изготовленная на заказ киберрука представляет собой Одноручный Экзотический Дробовик низкого качества, стреляющий с помощью навыка Оружие Крупного Калибра вместо навыка Тактическое оружие.С механической точки зрения, Дугомет — это дробовик, который может стрелять только с использованием альтернативного режима Выстрела Дробью, но при этом наносит 4d6 вместо 3d6 урона. Кроме того, вместо того, чтобы использовать боеприпасы, при каждом выстреле это оружие расходует один из 32 зарядов от легко перезаряжаемого (1 час) фирменного Аккумуляторного блока Радлайн МагнаСлот (100eb,входит в комплект при каждой покупке).Урон, наносимый этим оружием, не может нанести Критического Повреждения и не повреждает броню. Если урон, нанесенный этим оружием, уменьшит ПЗ цели до 1, то она Теряет Сознание с 1 ПЗ. Аккумулятор этого оружия можно извлечь и перезарядить в качестве Действия даже без свободной руки."
