    "description": "Ликвидатор Единичного Доступа - Система созданная для укрепления защиты от Быстрого Взлома.Опция Нейропорта.При каждой установке (максимум 3) в Нейропорт пользователя устанавливается один Заслон, обеспечивающий дополнительную линию защиты. Кроме того, с каждой установкой ИнтраЛьда СЛ всех Заслонов в Нейропорте пользователя увеличивается со Сл 6 при первой установке до Сл 8 при второй, а при третьей установке до Сл 10."
