    "humanityCostFormula": "14 (4d6)",
    "costEb": 100,
    "description": "Эти легендарные лезвия созданы с учетом смертоносности и скрытности. Они столь же эффективны, сколь и узнаваемы.Вариант Киберруки. Требуется 2 слота для опций Киберруки.Одноручное Тяжелое ОББ Отличного Качества, которое можно успешно спрятать без проверки, а также вытащить и спрятать без Действия. Пока оружие выдвинуто, пользователь не может ничего держать в этой руке. При покупке дважды и установке в две отдельных киберруки пользователь может свести на нет обычный штраф за передвижение при лазании, пока у него оба оружия выдвинуты."
