    "humanityCostFormula": "3 (1d6)",
    "costEb": 100,
    "description": "Имплантат, увеличивающий способность мозга хранить и обрабатывать информацию, связанную с Нетраном.Опция Нейролинка. Требуется Слот Нейропорта для Кибердеки.Каждая установка содержит слот Опции Оборудования для Кибердеки. Все Опции, установленые на Мега-Диск пользователя, считается установленным на любой Кибердеке, установленной в Слот Нейропорта для Кибердеки пользователя. Пользователь с двумя или более Мега-Дисками получает одно дополнительное Сетевое Действие каждый ход, когда он физически подключен к точке доступа вручную через свой Личный Разъем."
