    "notes": "Смартфон с обучающимся ИИ, который \"учится\", как лучше всего соответствовать потребностям, просто взаимодействуя с владельцем. Хоть это и не настоящий ИИ, но он способен заменить любого секретаря. Когда вы не задумываясь позволяете своему Агенту организовывать вашу жизнью, всё становится намного проще: вы занимаетесь своими делами (преступления, убийства людей, избежание наказания и т.д.) не переживая, что опять что-то забыли и снова надо идти в магазин. Существует много причин, почему Агент есть почти у каждого человека.Возможности вашего Агента:-Совершать голосовые или видеозвонки, записывать их, пересылать или отправлять на голосовую почту, которую в наше время кроме Агентов никто и не слушает.-Сёрфить по Дата Пулу.-Сканировать Дата Пул, чтобы найти необходимое место и отобразить маршрут.-Ведёт ваше расписание и самостоятельно выполняет действия, если нужно заказать подарок и отправить его получателю.-Имитирует личность с именем, голосом и виртуальным телом. Некоторые, особенно одинокие люди, программируют свой Агент на роль любовников ил друзей.-Предлагает подходящую для покупки одежду.Записывает аудио и видео на стандартную Щепку Памяти в Агенте.-Подключается к Киберимплантам чтобы копировать данные на Щепку памяти в Агенте.-Подключается к большинству приборов в вашем доме.-Отслеживает твой расход общедоступными товарами и автоматически заказывает их при снижении цены.-Рекомендует, как поступить исходя их твоих целей. ИИ может посоветовать неразумную чушь.В дополнение ко всему этому, Агент дает +2 к Навыку \"Поиск информации\" и +2 к Навыку \"Гардероб и Стиль\", но только при условии, что вы носите одежду, которую предлагает ваш Агент, (она меняется каждый сезон). Бонусы от нескольких Агентов не суммируются."
