    "notes": "Новая экипировка — так называемая Гидравлическая Подкладка, разработанный исландским стартапом Húsafell (теперь партнёр Sanroo) для городских боевых условий. Быстро стал популярен среди евросоло благодаря скрытности, малому весу и гидравлической поддержке верхней части тела, которая усиливает возможности пользователя в обращении с тяжёлым оружием — без внедрения киберимплантов. Многие евросоло утверждают, что спят в нём — ведь он полностью водонепроницаем. А ещё его можно мыть прямо на себе — в ванне, фьорде или под шлангом в саду. Когда надета, Гидравлическая Подкладка с гидроприводами увеличивает ТЕЛО на 2 Не может поднять ТЕЛО выше 10 Это увеличение не повышает ХП или Спасбросок. Не складывается с другими эффектами, повышающими ТЕЛО — например, Укреплёнными мышцами и Усиленными костями, Эндоскелетами и т.п."
