    "notes": "Электрогитара от Лазерного Света дает своему пользователю +1 к Проверкам навыка Игры на инструменте (Гитара). Этот бонус действует только один раз и не сочетается с другими инструментами, дающими бонусы к навыку игры на инструменте. Кроме того, при открытом ношении эта гитара считается за 1 установку Стилевой Светящейся Тату, что делает ее полезной для получения бонуса +2 к Гардеробу и Стилю за наличие 3 установленных Светящихся Тату."
